using FlexExtractor;
using System.Reflection;
using System.Windows.Forms;
static partial class Cases {
 static void Sta(Action action){Exception? failure=null;var thread=new Thread(()=>{try{action();}catch(Exception ex){failure=ex;}});thread.SetApartmentState(ApartmentState.STA);thread.Start();thread.Join();if(failure!=null)throw failure;}
 static IEnumerable<Control> AllControls(Control c){foreach(Control x in c.Controls){yield return x;foreach(var d in AllControls(x))yield return d;}}
 public static void TestAdvancedLabelsFitTheirColumns(){Sta(()=>{using var form=new FlexExtractor.UI.ConfigEditor(Cfg(Fresh()));form.Show();AllControls(form).OfType<TabControl>().Single().SelectedIndex=1;Application.DoEvents();Program.Check(AllControls(form).OfType<Label>().Any(x=>x.Text=="保留时长（天）"),"retention unit label clipped at observed DPI");foreach(var label in AllControls(form).OfType<Label>().Where(x=>x.Parent is TableLayoutPanel grid&&grid.GetColumn(x)==0)){var grid=(TableLayoutPanel)label.Parent!;var available=(int)grid.ColumnStyles[0].Width-label.Margin.Horizontal;Program.Check(TextRenderer.MeasureText(label.Text,label.Font).Width<=available,"label clipped: "+label.Text);}});}
 public static void TestStationRefreshUsesIsolatedWorker(){Sta(()=>{var c=Cfg(Fresh());Source(c,"partProcessed/deep/Request.xml");var t=Assembly.LoadFrom(Path.Combine(AppContext.BaseDirectory,"FlexRequestExtractor.dll")).GetType("FlexExtractor.UI.StationEditor")!;using var f=(Form)Activator.CreateInstance(t,c,c.DispenseItems[0])!;Program.Check(AllControls(f).Any(x=>x.Name=="RefreshSubFolders"),"isolated refresh action missing");f.Show();var task=(Task)Invoke(t,"RefreshAsync",f)!;var sw=System.Diagnostics.Stopwatch.StartNew();while(!task.IsCompleted&&sw.ElapsedMilliseconds<8000){Application.DoEvents();Thread.Sleep(10);}Program.Check(task.IsCompleted,"refresh did not complete");task.GetAwaiter().GetResult();var tree=AllControls(f).OfType<TreeView>().Single();Program.Check(tree.Nodes.Count==1&&tree.Nodes[0].Nodes.Count==1,"hierarchical refresh result missing");f.Close();});}
 public static void TestMainFormHasConfigThemeAndBoundedStatus(){var type=Assembly.LoadFrom(Path.Combine(AppContext.BaseDirectory,"FlexRequestExtractor.dll")).GetType("FlexExtractor.UI.MainForm");Program.Check(type!=null,"main work screen missing");Sta(()=>{var ctor=type!.GetConstructor(new[]{typeof(Config)});Program.Check(ctor!=null,"UI self-test must not read deployment config");using var f=(Form)ctor!.Invoke(new object[]{Cfg(Fresh())});var controls=AllControls(f).ToArray();foreach(var name in new[]{"OpenConfig","StartStop","Theme","Status","Log","Copied","Failed","Deleted","Skipped"})Program.Check(controls.Any(c=>c.Name==name),"missing main control "+name);Program.Check(!controls.OfType<TextBox>().Any(x=>!x.ReadOnly),"paths belong in config only");});}
 public static void TestConfigurationEditorHasExplicitFields(){var asmPath=Path.Combine(AppContext.BaseDirectory,"FlexRequestExtractor.dll");Program.Check(File.Exists(asmPath),"WinForms configuration editor missing");Sta(()=>{var t=Assembly.LoadFrom(asmPath).GetType("FlexExtractor.UI.ConfigEditor");Program.Check(t!=null,"ConfigEditor missing");using var form=(Form)Activator.CreateInstance(t!,Cfg(Fresh()))!;var controls=AllControls(form).ToArray();foreach(var name in new[]{"WatchRoot","PollIntervalSec","LookbackDays","KeepDays","OnlyNewAfterStart","NewFileGraceSec","MinFileBytes","SizeStableChecks","SizeStableIntervalMs","MaxLogLines","WorkerTimeoutSec","MaxFileBytes","MaxFilesPerPass","DispenseItems","BindItems","ImportLegacy","SaveConfig"})Program.Check(controls.Any(c=>c.Name==name),"missing UI field "+name);Program.Check(!controls.OfType<TextBox>().Any(x=>x.Multiline&&x.Text.Contains("SchemaVersion")),"raw JSON editing forbidden");});}
}
